using System.Security.Claims;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Modules.Planning;
using Shared.Primitives.Identifiers;

namespace Modules.Planning;

public static class PlanningModuleExtensions
{
    public static IServiceCollection AddPlanningModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, PlanningModuleManifestProvider>();
        services.AddSingleton<PlanningRepository>();
        services.AddSingleton<PlanningFormulaEngine>();
        return services;
    }

    public static WebApplication MapPlanningModule(this WebApplication app)
    {
        var g = app.MapGroup("/api/v1/planning").WithTags("Planning").RequireAuthorization().RequireRateLimiting("api");
        g.MapGet("/cycles", async (Guid? legalEntityId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.cycles.read", legalEntityId, () => r.ListCyclesAsync(Tenant(h), legalEntityId, ct)));
        g.MapPost("/cycles", async (CreatePlanningCycleRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.cycles.manage", q.LegalEntityId, () => r.CreateCycleAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        foreach (var action in new[] { "open", "submit", "approve", "publish", "close", "archive" })
            g.MapPost("/cycles/{id:guid}/" + action, async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, action is "approve" or "publish" ? "planning.versions.approve" : "planning.cycles.manage", null, () => r.AdvanceCycleAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/models", async (CreatePlanningModelRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", q.LegalEntityId, () => r.CreateModelAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/model-versions", async (CreateModelVersionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.models.manage", null, () => r.CreateModelVersionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/versions", async (CreatePlanVersionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", null, () => r.CreatePlanVersionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/versions", async (HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.versions.read", null, () => r.ListPlanVersionsAsync(Tenant(h), ct)));
        g.MapPost("/versions/{id:guid}/clone", async (Guid id, string? name, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", null, () => r.ClonePlanVersionAsync(Tenant(h), Actor(h), id, name ?? "", ct), ct, 201));
        foreach (var action in new[] { "submit", "approve", "publish", "close" })
            g.MapPost("/versions/{id:guid}/" + action, async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, action switch { "submit" => "planning.versions.submit", "approve" => "planning.versions.approve", "publish" => "planning.versions.publish", _ => "planning.versions.edit" }, null, () => r.AdvanceVersionAsync(Tenant(h), Actor(h), id, action, ct), ct));
        g.MapPost("/versions/{id:guid}/recalculate", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", null, () => r.RecalculateAsync(Tenant(h), Actor(h), id, ct), ct, 202));
        g.MapPost("/scenarios", async (CreateScenarioRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.create", null, () => r.CreateScenarioAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/scenarios/{id:guid}/clone", async (Guid id, string? name, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.scenarios.create", null, () => r.CloneScenarioAsync(Tenant(h), Actor(h), id, name ?? "", ct), ct, 201));
        g.MapPost("/grids/query", async (GridQueryRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.versions.read", q.LegalEntityId, () => r.QueryGridAsync(Tenant(h), q, ct)));
        g.MapPost("/grids/write-batch", async (GridWriteRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.Cells.Count > 0 ? q.Cells[0].LegalEntityId : null, () => r.WriteGridAsync(Tenant(h), Actor(h), q, ct), ct));
        g.MapPost("/grids/spread", async (GridWriteRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.Cells.Count > 0 ? q.Cells[0].LegalEntityId : null, () => r.WriteGridAsync(Tenant(h), Actor(h), q, ct), ct));
        g.MapPost("/grids/paste-preview", async (GridWriteRequest q, HttpContext h, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.versions.read", q.Cells.Count > 0 ? q.Cells[0].LegalEntityId : null, () => Task.FromResult<IReadOnlyList<GridCellRequest>>(q.Cells)));
        g.MapPost("/assumptions", async (CreateAssumptionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.assumptions.manage", null, () => r.CreateAssumptionAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/assumptions/{id:guid}/values", async (Guid id, AssumptionValueRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.assumptions.manage", null, () => r.SetAssumptionValueAsync(Tenant(h), id, q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        g.MapPost("/budget/baselines", async (CreateBaselineRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.manage", null, () => r.CreateBaselineAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/budget/baselines/{id:guid}/revisions", async (Guid id, RevisionRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.revision", null, () => r.ApproveRevisionAsync(Tenant(h), Actor(h), id, q, ct).ContinueWith(_ => new { approved = true }, ct), ct));
        g.MapGet("/budget/baselines/{id:guid}/current", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.budget.read", null, () => r.CurrentBudgetAsync(Tenant(h), id, ct)));
        g.MapPost("/budget/policies", async (Guid legalEntityId, string name, string mode, string basis, decimal thresholdPercent, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.manage", legalEntityId, () => r.CreatePolicyAsync(Tenant(h), Actor(h), legalEntityId, name, mode, basis, thresholdPercent, ct), ct, 201));
        g.MapPost("/budget/buckets", async (BudgetBucketRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.manage", q.LegalEntityId, () => r.CreateBucketAsync(Tenant(h), q, ct), ct, 201));
        g.MapPost("/budgets/{id:guid}/transfers", async (Guid id, TransferRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.transfer", null, () => r.CreateBudgetTransferAsync(Tenant(h), Actor(h), id, q, ct), ct, 201));
        g.MapPost("/budget/check", async (BudgetCheckRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.budget_control.read", null, () => r.CheckBudgetAsync(Tenant(h), Actor(h), q with { Reserve = false }, ct)));
        g.MapPost("/budget/check-and-reserve", async (BudgetCheckRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget_control.read", null, () => r.CheckBudgetAsync(Tenant(h), Actor(h), q with { Reserve = true }, ct), ct));
        g.MapGet("/budget/buckets/{id:guid}/availability", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.budget_control.read", null, () => r.AvailabilityAsync(Tenant(h), id, ct)));
        g.MapPost("/budget/reservations/{id:guid}/release", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget_control.read", null, () => r.ReleaseReservationAsync(Tenant(h), Actor(h), id, ct).ContinueWith(_ => new { released = true }, ct), ct));
        g.MapPost("/budget-transfers/{id:guid}/approve", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.budget.transfer.approve", null, () => r.ApproveTransferAsync(Tenant(h), Actor(h), id, ct), ct));
        g.MapPost("/workforce", async (WorkforcePlanRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.LegalEntityId, () => r.AddWorkforceAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapGet("/workforce", async (Guid planVersionId, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.workforce.read", null, () => r.ListWorkforceAsync(Tenant(h), planVersionId, ct)));
        g.MapPost("/capex", async (CapexPlanRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.capex.manage", q.LegalEntityId, () => r.AddCapexAsync(Tenant(h), Actor(h), q, ct), ct, 201));
        g.MapPost("/revenue", async (RevenueDriverRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.LegalEntityId, () => r.AddRevenueDriverAsync(Tenant(h), q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        g.MapPost("/working-capital", async (WorkingCapitalRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", q.LegalEntityId, () => r.AddWorkingCapitalAsync(Tenant(h), q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        g.MapPost("/fx", async (PlanningFxRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.versions.edit", null, () => r.AddFxRateAsync(Tenant(h), q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        g.MapPost("/actuals/refresh", async (ActualRefreshRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.actuals.refresh", null, () => r.RefreshActualsAsync(Tenant(h), Actor(h), q, ct), ct, 202));
        g.MapGet("/actuals/refresh-runs/{id:guid}", async (Guid id, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.actuals.refresh", null, () => r.GetActualRefreshRunAsync(Tenant(h), id, ct)));
        g.MapPost("/variance/query", async (VarianceQueryRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, CancellationToken ct) => await Read(h, s, a, "planning.variance.read", q.LegalEntityId, () => r.QueryVarianceAsync(Tenant(h), q, ct)));
        g.MapPost("/variance/commentary", async (CommentRequest q, HttpContext h, PlanningRepository r, IAuthorizationSubjectStore s, IPermissionAuthorizer a, IModuleLifecycleEnforcer l, CancellationToken ct) => await Mutate(h, s, a, l, "planning.variance.read", null, () => r.AddCommentAsync(Tenant(h), Actor(h), q, ct).ContinueWith(_ => new { saved = true }, ct), ct));
        return app;
    }

    private static TenantId Tenant(HttpContext h) => Guid.TryParse(h.User.FindFirstValue("tenant_id"), out var id) ? new(id) : throw new PlanningException("tenant.context_required");
    private static Guid Actor(HttpContext h) => Guid.TryParse(h.User.FindFirstValue(ClaimTypes.NameIdentifier), out var id) ? id : throw new PlanningException("identity.required");
    private static async Task<IResult> Read<T>(HttpContext h, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, string permission, Guid? entity, Func<Task<T>> action)
    { var access = await Access(h, store, authorizer, permission, entity, h.RequestAborted); if (!access) return Results.Forbid(); return await Execute(action, h.RequestAborted); }
    private static async Task<IResult> Mutate<T>(HttpContext h, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, IModuleLifecycleEnforcer lifecycle, string permission, Guid? entity, Func<Task<T>> action, CancellationToken ct, int status = 200)
    { var access = await Access(h, store, authorizer, permission, entity, ct); if (!access) return Results.Forbid(); if (!await lifecycle.CanMutateAsync(Tenant(h), "planning", entity, ct)) return Results.Problem(statusCode: 403, title: "module.lifecycle_readonly", extensions: new Dictionary<string, object?> { ["code"] = "module.lifecycle_readonly" }); return await Execute(action, ct, status); }
    private static async Task<bool> Access(HttpContext h, IAuthorizationSubjectStore store, IPermissionAuthorizer authorizer, string permission, Guid? entity, CancellationToken ct)
    { if (!Guid.TryParse(h.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(h.User.FindFirstValue("membership_id"), out var membershipId)) return false; var subject = await store.LoadAsync(new TenantId(tenantId), membershipId, ct); if (subject is null) return false; var scope = entity is { } e ? PermissionScope.ForLegalEntity(new TenantId(tenantId), new LegalEntityId(e)) : PermissionScope.ForTenant(new TenantId(tenantId)); return authorizer.Authorize(subject, permission, scope); }
    private static async Task<IResult> Execute<T>(Func<Task<T>> action, CancellationToken ct, int status = 200) { try { var value = await action(); return status == 201 ? Results.Created("", value) : status == 202 ? Results.Accepted("", value) : Results.Ok(value); } catch (PlanningException ex) { var code = ex.Code; var sc = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code.Contains("immutable", StringComparison.Ordinal) || code.Contains("insufficient", StringComparison.Ordinal) || code.Contains("transition", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: sc, title: code, extensions: new Dictionary<string, object?> { ["code"] = code }); } }
}

